def process(clean_theft_data) -> pd.DataFrame:
    df = clean_theft_data
    growth_by_type = []

    for theft_type in df['Theft Type'].unique():
        type_data = df[df['Theft Type'] == theft_type].sort_values('Year')
        if len(type_data) >= 2:
            first_year = type_data[type_data['Year'] == 2020]['Reports'].values
            last_year = type_data[type_data['Year'] == 2024]['Reports'].values

            if len(first_year) > 0 and len(last_year) > 0:
                reports_2020 = first_year[0]
                reports_2024 = last_year[0]
                relative_growth = ((reports_2024 - reports_2020) / reports_2020) * 100
                growth_by_type.append({
                    'Theft Type': theft_type,
                    'Reports 2020': reports_2020,
                    'Reports 2024': reports_2024,
                    'Relative Growth %': relative_growth
                })

    return pd.DataFrame(growth_by_type).sort_values('Relative Growth %', ascending=False)

