def process(clean_theft_data) -> pd.DataFrame:
    df = clean_theft_data
    growth = []
    for theft_type in df['Theft Type'].unique():
        data_2020 = df[(df['Theft Type'] == theft_type) & (df['Year'] == 2020)]['Reports'].values
        data_2024 = df[(df['Theft Type'] == theft_type) & (df['Year'] == 2024)]['Reports'].values

        if len(data_2020) > 0 and len(data_2024) > 0:
            reports_2020 = data_2020[0]
            reports_2024 = data_2024[0]
            growth_rate = ((reports_2024 - reports_2020) / reports_2020) * 100
